-- Reference only: already applied to isolated Neon branch br-fancy-heart-axjf1fzn.
-- This is a temporary UAT fixture setup, not an application migration. Do not run against production.
-- Failure triggers match only the six named simulated fixtures. Existing UAT jobs are unaffected.













CREATE FUNCTION froto_uat_fee_failure_20261001() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF COALESCE(NEW.metadata->>'spotRequirementId',NEW.metadata->>'listingId',NEW.metadata->>'tenderId') IN ('uat-rollback-spot-fee-20261001','uat-rollback-marketplace-fee-20261001','uat-rollback-tender-fee-20261001') THEN RAISE EXCEPTION 'FROTO_UAT_INJECTED_FEE_FAILURE'; END IF; RETURN NEW; END; $$;

CREATE TRIGGER froto_uat_fee_failure_20261001 BEFORE INSERT ON "TransactionFee" FOR EACH ROW EXECUTE FUNCTION froto_uat_fee_failure_20261001();

CREATE FUNCTION froto_uat_notification_failure_20261001() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF COALESCE(NEW.metadata->>'spotRequirementId',NEW.metadata->>'listingId',NEW.metadata->>'tenderId') IN ('uat-rollback-spot-notification-20261001','uat-rollback-marketplace-notification-20261001','uat-rollback-tender-notification-20261001') AND NEW.type IN ('SPOT_REQUIREMENT_AWARD_UNSUCCESSFUL','MARKETPLACE_AWARD_UNSUCCESSFUL','TENDER_AWARD_UNSUCCESSFUL') THEN RAISE EXCEPTION 'FROTO_UAT_INJECTED_NOTIFICATION_FAILURE'; END IF; RETURN NEW; END; $$;

CREATE TRIGGER froto_uat_notification_failure_20261001 BEFORE INSERT ON "Notification" FOR EACH ROW EXECUTE FUNCTION froto_uat_notification_failure_20261001();
